import ast
# Check all Python files in the groupchat/history directory
import os
errors = []
for root, dirs, files in os.walk('nanobot/groupchat/history'):
    for f in files:
        if f.endswith('.py'):
            path = os.path.join(root, f)
            try:
                with open(path) as fh:
                    ast.parse(fh.read())
            except SyntaxError as e:
                errors.append(f'{path}: {e}')

if errors:
    for e in errors:
        print(e)
else:
    print('All files parse OK')
"
